// ====== EDIT YOUR SETTINGS HERE ======
return [{ json: {
  send_mode: 'draft',                                   // 'draft' = create Gmail drafts for your review. 'send' = fully automatic.
  run_scraper: true,                                    // false = reuse the latest export instead of scraping fresh
  jobs_dir: '/Users/app/Desktop/GTM_Jobs',
  scraper_dir: '/Users/app/gtm-job-scraper',
  outreach_dir: '/Users/app/gtm-job-scraper/outreach',
  work_dir: '/tmp/gtm_outreach',
  max_employees: 400,                                    // skip companies estimated bigger than this (AI estimate from JD)
  model: 'claude-sonnet-4-6',                           // default; bump to 'claude-opus-4-8' for max quality
  chrome: '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome'
} }];

const STRONG = /gtm|go.to.market/i;
const slug = s => s.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
const byCompany = new Map();
for (const item of $input.all()) {
  const j = item.json;
  const company = (j.company || '').trim();
  const title = (j.position || '').trim();
  if (!company || !title) continue;
  if (!STRONG.test(title)) continue;
  const score = /gtm engineer|go.to.market engineer/i.test(title) ? 2 : 1;
  const key = company.toLowerCase();
  const cur = byCompany.get(key);
  if (!cur || score > cur.score) byCompany.set(key, { score, job: j });
}
return [...byCompany.values()]
  .sort((a, b) => b.score - a.score)
  .map(({ job }) => ({ json: { ...job, company_slug: slug(job.company) } }));

const contacted = new Set(
  $input.all()
    .map(i => ((i.json.company || '') + '').trim().toLowerCase())
    .filter(Boolean)
);
return $('Prepare Jobs').all().filter(i => !contacted.has(i.json.company.trim().toLowerCase()));

const job = $('Build Strategist Prompt').item.json;
const res = $input.item.json || {};
let text = (res.content && res.content[0] && res.content[0].text) || '{}';
text = text.replace(/^```(json)?\s*/m, '').replace(/```\s*$/m, '').trim();
let out;
try { out = JSON.parse(text); }
catch (e) { out = { email_subject: 'GTM engineer for ' + job.company, email_body: text, one_liner: '', gtm_insights: [] }; }
const { prompt, ...rest } = job;
let body = out.email_body || '';
const LINK = 'https://calendly.com/arsal4527/gtm-strategy';
if (body && body.indexOf('calendly.com/arsal4527') === -1) {
  body = body.replace(/\s+$/, '') + '\n\nP.S. easiest to grab 15 min here: ' + LINK;
}
const cfg = $('Config').first().json;
const proof = [];
if (cfg.resume_url && cfg.resume_url.indexOf('YOUR_') === -1) proof.push('Resume: ' + cfg.resume_url);
if (proof.length) body = body.replace(/\s+$/, '') + '\n\n' + proof.join(' / ');
const bodyWords = body.split(/\s+/).filter(Boolean).length;
const BANNED_PHRASES = ['i hope this finds you well','i wanted to reach out','i came across','please find attached','just following up','just checking in','as per my last email','would love to','excited to','please consider'];
const bodyLower = body.toLowerCase();
const bannedHit = BANNED_PHRASES.find(p => bodyLower.includes(p));
const startsWithI = /^i\b/i.test(body.trim());
const hasCTA = /\?|calendly\.com/i.test(body);
let qualityFailReason = '';
if (bodyWords < 60) qualityFailReason = 'too_short_' + bodyWords + '_words';
else if (bodyWords > 180) qualityFailReason = 'too_long_' + bodyWords + '_words';
else if (bannedHit) qualityFailReason = 'banned: ' + bannedHit;
else if (startsWithI) qualityFailReason = 'starts_with_I';
else if (!hasCTA) qualityFailReason = 'no_CTA';
const qualityPass = !qualityFailReason;
return { json: { ...rest,
  gtm_insights: Array.isArray(out.gtm_insights) ? out.gtm_insights.join(' | ') : ((out.gtm_insights || '') + ''),
  one_liner: out.one_liner || '',
  email_subject: out.email_subject || ('GTM engineer for ' + job.company),
  email_body: body,
  quality_pass: qualityPass,
  skip_reason: qualityPass ? '' : ('quality_fail: ' + qualityFailReason),
} };

const job = $('Build Resume Prompt').item.json;
const res = $input.item.json || {};
let html = (res.content && res.content[0] && res.content[0].text) || '';
html = html.replace(/^```(html)?\s*/m, '').replace(/```\s*$/m, '').trim();
const template = $('Load Template').first().json.stdout;
const { prompt, ...rest } = job;
return { json: { ...rest, resume_html: template.replace('{{CONTENT}}', html) } };

const full = $('Build Resume HTML').item.json;
const { resume_html, prompt, ...job } = full;
const binary = $input.item.binary || {};
if (binary.data) {
  binary.data.fileName = 'Resume - ' + (job.company || 'Company') + '.pdf';
  binary.data.mimeType = 'application/pdf';
}
return { json: job, binary };

const job = $('Resolve Domain').item.json;
const cfg = $('Config').first().json;
const r = $input.item.json || {};
const data = r.data || {};
const emails = Array.isArray(data.emails) ? data.emails : [];
const domain = data.domain || '';

// Hunter returns headcount as a range string (e.g. "11-50", "201-500", "1001-5000", "10001+").
// Use midpoint for filtering; unknown headcount passes through (don't drop free leads).
const hc = (data.headcount || '').trim();
const HEADCOUNT_MID = {
  '1-10': 5, '11-50': 30, '51-200': 125, '201-500': 350,
  '501-1000': 750, '1001-5000': 3000, '5001-10000': 7500, '10001+': 15000
};
const mid = HEADCOUNT_MID[hc] || 0;
const cap = Number(cfg.max_employees || 400);
if (mid && mid > cap) {
  return { json: { ...job, contact_found: false, company_domain: domain,
    company_headcount: hc, est_employees: mid,
    skip_reason: 'too_big_~' + mid + '_(' + hc + ')' } };
}

function rank(pos){
  pos=(pos||'').toLowerCase();
  if(/founder|co-?founder|owner/.test(pos)) return 0;
  if(/\bceo\b|chief executive/.test(pos)) return 1;
  if(/\bcro\b|chief revenue/.test(pos)) return 2;
  if(/(vp|vice president|head|director).*(revenue|sales)/.test(pos)) return 3;
  if(/(vp|vice president|head|director).*(growth)/.test(pos)) return 4;
  if(/\bcmo\b|(vp|vice president|head|director).*(marketing)/.test(pos)) return 5;
  if(/revenue operations|revops|sales operations/.test(pos)) return 6;
  if(/founder|chief|vp|vice president|head|director|lead/.test(pos)) return 7;
  return 9;
}
let best=null;
for(const e of emails){
  const email=((e.value||'')+'').trim();
  if(!email.includes('@')) continue;
  const conf=Number(e.confidence||0);
  if(conf < 50) continue;
  const score = rank(e.position)*1000 - conf;
  if(!best || score < best.score) best={score, e, conf};
}
if(!best){
  return { json: { ...job, contact_found:false, company_domain:domain,
    company_headcount: hc,
    skip_reason: emails.length ? 'no_confident_contact' : 'no_emails_found' } };
}
const e=best.e;
const name=((e.first_name||'')+' '+(e.last_name||'')).trim();
return { json: { ...job,
  contact_found:true,
  company_domain: domain,
  company_website: domain ? ('https://'+domain) : (job.company_website||''),
  company_headcount: hc || job.company_headcount || '',
  est_employees: mid,
  contact_name: name,
  contact_title: e.position || '',
  contact_email: e.value,
  contact_linkedin: e.linkedin || '',
  email_score: best.conf } };
